// KEIS 搶單通知：收 grab.py POST 進來的 payload，組成 LINE 訊息
const body = $input.first().json.body || $input.first().json;
const USER_ID = "Ufab42c56b2eb9b9a9ff18c367b85a6dd"; // 薛力瑜

// 三段式漏斗，2026-08-04 改成直排（一行一個數字，手機上一眼看完）：
//   全新名單 ＝ 公買今天真正新放進池子的貨（已扣掉二手回鍋、扣掉全池掃描補到的老編號）
//   符合條件 ＝ 其中通過篩選、輪得到我們搶的
//   實際拿到 ＝ 真的申請成功的
// 掛 0 時要分得出「沒出貨」「出了但不符條件」「符合卻搶輸」三種，所以三個數字缺一不可。
// match_today 是後加的欄位；舊 payload 沒帶就退回 new_today（當年那個數字其實就是符合條件數）。
const stats = (b) => {
  const seen = b.new_today || 0;
  const match = (b.match_today != null) ? b.match_today : seen;
  const got = b.grabbed_today || 0;
  return {
    seen, match, got,
    block: `　全新名單 ${seen} 筆\n　符合條件 ${match} 筆\n　實際拿到 ${got} 筆`,
    line: `全新名單 ${seen} ／ 符合條件 ${match} ／ 實際拿到 ${got}`,
  };
};

// 三個數字講完之後那句白話結論
const verdict = (s, pending) => {
  if (s.got > 0) {
    const missed = s.match - s.got;
    return missed > 0
      ? `⚠ 有 ${missed} 筆符合條件${pending ? '還沒' : '卻沒'}搶到（搶輸／配額滿）`
      : '✅ 符合條件的全打中';
  }
  if (s.seen === 0) return '✅ 公買沒出新貨，系統正常運作，只是沒貨可搶';
  if (s.match === 0) return `ℹ️ 出了 ${s.seen} 筆新貨但沒有一筆符合條件，不是搶輸`;
  return `⚠ 有 ${s.match} 筆符合條件卻一筆都沒搶到（搶輸／配額滿）`;
};

let text;
if (body.event === 'alert') {
  text = body.text || '⚠ KEIS 搶單警示';
} else if (body.event === 'daily_summary') {
  // 跨日結算保底：每天換日瞬間推一則「前一天」戰果（掛 0 那天也一定有訊息）。
  // 系統是全天分層輪詢、沒有「收工」這回事，措辭別讓人以為要停了。
  const s = stats(body);
  const recovered = body.recovered || 0;
  const d = body.date || '';
  const rec = recovered > 0 ? `\n　（另補回 ${recovered} 筆漏記）` : '';
  text = `🌙 KEIS 跨日結算（${d} 戰果）\n${s.block}${rec}\n${verdict(s, false)}\n🔄 系統持續 24H 監控中`;
} else {
  const g = body.grabbed || [];
  const lines = g.map(x => `・${x.name} ${x.phone}｜${x.city} ${x.category} ${x.budget}`).join('\n');
  const left = (body.quota_left != null) ? body.quota_left : '?';
  if (body.new_today != null) {
    // 開盤搶到：帶今日累計，一眼分辨貨少 vs 不符條件 vs 搶輸
    const s = stats(body);
    text = `🎯 KEIS 這批搶到 ${g.length} 筆\n\n`
         + `📊 今天累計\n${s.block}\n🎟 剩餘配額 ${left}\n`
         + `${verdict(s, true)}\n\n${lines}`;
  } else if (body.source === 'reconcile') {
    // 回查補回：這批「不是機器人當場搶的」，是去問 KEIS「這帳號申請過哪些」比對出來的。
    // 2026-07-29 踩過：一筆 07 開頭市話半夜冒出來，看起來像機器人壞掉亂搶，
    // 其實是有人用該帳號手動申請、機器人只是把它補記下來。訊息不講清楚就會嚇到人。
    const marked = g.map(x => {
      const d = String(x.phone || '').replace(/\D/g, '');
      const mob = d.startsWith('09') || d.startsWith('9');
      return `・${x.name} ${x.phone}${mob ? '' : ' ☎️市話'}｜${x.city} ${x.category} ${x.budget}`;
    }).join('\n');
    text = `↩ KEIS 補回 ${g.length} 筆漏記名單\n`
         + `ℹ️ 不是機器人搶的——回查 KEIS 發現這些已掛在我們帳號下（多半是有人手動申請），補記進來\n`
         + `🎟 目前剩餘配額 ${left}\n\n${marked}`;
  } else {
    // 其他沒帶今日累計的情況：退回本批數
    text = `🎯 KEIS 搶到 ${g.length} 筆（目前剩餘配額 ${left}）\n\n${lines}`;
  }
}
return [{ json: { userId: USER_ID, text } }];
